<script setup>
import { ref } from 'vue'
defineProps({ brands: { type: Array, default: () => [] }, selected: String })
defineEmits(['select'])
const track = ref(null)
const move = (direction) => track.value?.scrollBy({ left: direction * 520, behavior: 'smooth' })
</script>
<template><section v-if="brands.length" class="py-12"><div class="mb-5 flex items-end justify-between"><div><p class="text-xs font-semibold uppercase tracking-[0.22em] text-gold-400">Explorá por marca</p><h2 class="mt-2 font-display text-3xl">Marcas destacadas</h2></div><div class="hidden gap-2 sm:flex"><button class="flex h-11 w-11 items-center justify-center rounded-full border border-white/10 bg-panel text-xl text-gold-300 transition hover:border-gold-400 hover:bg-gold-400 hover:text-ink" aria-label="Marcas anteriores" @click="move(-1)">←</button><button class="flex h-11 w-11 items-center justify-center rounded-full border border-white/10 bg-panel text-xl text-gold-300 transition hover:border-gold-400 hover:bg-gold-400 hover:text-ink" aria-label="Más marcas" @click="move(1)">→</button></div></div><div class="relative"><div ref="track" class="flex snap-x snap-mandatory gap-3 overflow-x-auto pb-4 luxury-scroll"><button v-for="brand in brands" :key="brand" class="group min-w-[150px] snap-start rounded-2xl border px-5 py-5 text-center text-sm font-semibold transition-all" :class="selected === brand ? 'border-gold-400 bg-gold-400 text-ink shadow-xl shadow-gold-400/10' : 'border-white/10 bg-gradient-to-br from-panel to-black text-zinc-300 hover:-translate-y-0.5 hover:border-gold-400/40 hover:text-gold-300'" @click="$emit('select', brand)"><span class="block font-display text-lg">{{ brand }}</span><span class="mt-1 block text-[9px] uppercase tracking-widest opacity-50">Ver fragancias</span></button></div></div></section></template>
